-- Roll back only products generated by scripts/generate_1000_products.py.
SET NAMES utf8mb4;
START TRANSACTION;

DELETE pi
FROM product_image pi
JOIN product p ON p.id = pi.product_id
WHERE p.product_no BETWEEN 'SP300001' AND 'SP301000';

DELETE ps
FROM product_sku ps
JOIN product p ON p.id = ps.product_id
WHERE p.product_no BETWEEN 'SP300001' AND 'SP301000';

DELETE FROM product
WHERE product_no BETWEEN 'SP300001' AND 'SP301000';

COMMIT;

SELECT COUNT(*) AS remaining_generated_products
FROM product
WHERE product_no BETWEEN 'SP300001' AND 'SP301000';
